const projects = yield* Database.query(Filter.type(types['org.dxos.type.project'])).run;
const ps = projects.find(x => x.name === 'Platform Stability');
const is = projects.find(x => x.name === 'Indexer stability');
const psTs = yield* Database.load(ps.taskSet);
const isTs = yield* Database.load(is.taskSet);
const moveIds = ['01JZZZZZZZZZZZZZZZZZZZZZZ3','01JZZZZZZZZZZZZZZZZZZZZZZ4','01JZZZZZZZZZZZZZZZZZZZZZZ5','01JZZZZZZZZZZZZZZZZZZZZZZ6'];
const idxToMove = [];
for (let i = 0; i < psTs.tasks.length; i++) {
  const r = yield* Effect.result(Database.load(psTs.tasks[i]));
  if (r.success && moveIds.includes(r.success.id)) idxToMove.push(i);
}
yield* print('indices', JSON.stringify(idxToMove));
const movedRefs = idxToMove.map(i => psTs.tasks[i]);
Obj.update(psTs, (ts) => {
  for (const i of [...idxToMove].reverse()) ts.tasks.splice(i, 1);
});
Obj.update(isTs, (ts) => {
  for (const r of movedRefs) ts.tasks.push(r);
});
yield* Database.flush();
yield* print('PS now', psTs.tasks.length, 'IS now', isTs.tasks.length);

