const Spec = yield* Database.resolve('dxn:org.dxos.type.projects.spec:0.1.0');
const Feature = yield* Database.resolve('dxn:org.dxos.type.feature:0.3.0');

const specs = yield* Database.query(Filter.type(Spec)).run;
const features = yield* Database.query(Filter.type(Feature)).run;

// group features by their target spec id
const bySpec = new Map();
for (const f of features) {
  if (f.spec) {
    const id = f.spec.target?.id ?? f.spec.id ?? f.spec.dxn?.toString();
    if (!bySpec.has(id)) bySpec.set(id, []);
    bySpec.get(id).push(f);
  }
}

function aggregateStatus(feats) {
  const statuses = feats.map(f => f.status);
  if (statuses.includes('failing')) return 'failing';
  if (statuses.length > 0 && statuses.every(s => s === 'operational')) return 'operational';
  if (statuses.some(s => s === 'operational' || s === 'prototype')) return 'prototype';
  return 'planned';
}

for (const s of specs) {
  const feats = bySpec.get(s.id) ?? [];
  yield* print(s.id, s.name, '-> features:', feats.length, 'agg status:', aggregateStatus(feats));
